import React, { useState, useContext } from 'react';
import axios from 'axios';
import { ethers } from 'ethers';
import { Web3Context } from '../contexts/Web3Context';
import { UIContext } from '../App'; 

const CreatorStudio = () => {
  const { currentAccount } = useContext(Web3Context);
  const { showToast } = useContext(UIContext);
  
  const [formData, setFormData] = useState({
    title: "",
    topic: "Grammar",
    price: 0.0001,
    questions: [{ question_content: "", options: ["", "", "", ""], correct_option_index: 0 }]
  });
  
  const [loading, setLoading] = useState(false);

  // Hàm xử lý thay đổi input
  const handleQuestionChange = (index, field, value) => {
    const newQuestions = [...formData.questions];
    newQuestions[index][field] = value;
    setFormData({ ...formData, questions: newQuestions });
  };

  const handleOptionChange = (qIndex, oIndex, value) => {
    const newQuestions = [...formData.questions];
    newQuestions[qIndex].options[oIndex] = value;
    setFormData({ ...formData, questions: newQuestions });
  };

  const addQuestion = () => {
    if (formData.questions.length >= 20) return alert("Tối đa 20 câu thôi!");
    setFormData({
      ...formData,
      questions: [...formData.questions, { question_content: "", options: ["", "", "", ""], correct_option_index: 0 }]
    });
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    if (!currentAccount) return showToast('error', "Kết nối ví trước!");

    setLoading(true);
    try {
      // 1. Trả phí đăng bài (Ví dụ: 0.0005 ETH phí niêm yết)
      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner();
      const listingFee = ethers.parseEther("0.0005"); 
      
      const tx = await signer.sendTransaction({
        to: "0xYourTreasuryAddressHere", // Địa chỉ ví Admin/Quỹ hệ thống nhận phí
        value: listingFee
      });
      await tx.wait();

      // Lưu log biến động số dư
      await axios.post('http://localhost:5000/api/transaction/log', {
          user_address: currentAccount,
          type: 'CREATE_FEE',
          amount: -0.0005,
          tx_hash: tx.hash,
          description: `Phí đăng bài: ${formData.title}`
      });

      // 2. Gửi lên Server
      const res = await axios.post('http://localhost:5000/api/exercises/create', {
        ...formData,
        creator_address: currentAccount,
        tx_hash: tx.hash
      });

      if (res.data.success) {
        showToast('success', "Đăng bài thành công!");
      } else {
        showToast('error', res.data.message);
      }

    } catch (err) {
      showToast('error', "Lỗi: " + err.message);
    }
    setLoading(false);
  };

  return (
    <div className="pt-24 pb-10 px-6 max-w-4xl mx-auto">
      <div className="glass-panel p-8">
        <h2 className="text-3xl font-bold text-white mb-6">Creator Studio - Tạo Đề Thi</h2>
        
        <form onSubmit={onSubmit} className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <input 
              className="p-3 bg-slate-800 rounded text-white" 
              placeholder="Tên bài thi (VD: Ôn tập thì quá khứ)" 
              value={formData.title}
              onChange={e => setFormData({...formData, title: e.target.value})}
              required
            />
            <select 
              className="p-3 bg-slate-800 rounded text-white"
              value={formData.topic}
              onChange={e => setFormData({...formData, topic: e.target.value})}
            >
              <option value="Grammar">Ngữ pháp</option>
              <option value="Vocabulary">Từ vựng</option>
              <option value="IELTS">IELTS</option>
            </select>
          </div>

          <div className="p-3 bg-slate-800 rounded text-white flex items-center justify-between">
             <span>Giá bán bài thi (ETH):</span>
             <input 
                type="number" step="0.0001" 
                className="w-32 p-1 bg-slate-700 rounded ml-2"
                value={formData.price}
                onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
             />
          </div>

          <hr className="border-white/10 my-6"/>

          {formData.questions.map((q, qIdx) => (
            <div key={qIdx} className="bg-white/5 p-4 rounded-xl border border-white/10 mb-4">
              <div className="flex justify-between mb-2">
                <span className="font-bold text-indigo-400">Câu hỏi #{qIdx + 1}</span>
                {qIdx > 0 && <button type="button" className="text-red-400 text-sm" onClick={() => {
                    const newQ = [...formData.questions];
                    newQ.splice(qIdx, 1);
                    setFormData({...formData, questions: newQ});
                }}>Xóa</button>}
              </div>
              
              <textarea 
                className="w-full p-3 bg-slate-900 rounded mb-3" 
                placeholder="Nội dung câu hỏi..."
                value={q.question_content}
                onChange={e => handleQuestionChange(qIdx, 'question_content', e.target.value)}
                required
              />

              <div className="grid grid-cols-2 gap-3">
                {q.options.map((opt, oIdx) => (
                  <input 
                    key={oIdx}
                    className="p-2 bg-slate-900 rounded text-sm"
                    placeholder={`Đáp án ${oIdx + 1}`}
                    value={opt}
                    onChange={e => handleOptionChange(qIdx, oIdx, e.target.value)}
                    required
                  />
                ))}
              </div>

              <div className="mt-3 flex items-center gap-2">
                <span className="text-sm text-gray-400">Đáp án đúng:</span>
                <select 
                  className="w-20 p-1 bg-slate-700 rounded"
                  value={q.correct_option_index}
                  onChange={e => handleQuestionChange(qIdx, 'correct_option_index', parseInt(e.target.value))}
                >
                  <option value={0}>1</option>
                  <option value={1}>2</option>
                  <option value={2}>3</option>
                  <option value={3}>4</option>
                </select>
              </div>
            </div>
          ))}

          <button type="button" onClick={addQuestion} className="w-full py-2 border-2 border-dashed border-gray-600 text-gray-400 rounded-xl hover:border-indigo-500 hover:text-indigo-500 transition">
            + Thêm câu hỏi
          </button>

          <button type="submit" disabled={loading} className="btn-gradient w-full py-4 text-lg font-bold shadow-xl">
            {loading ? "Đang xử lý..." : `Thanh toán phí 0.0005 ETH & Đăng bài`}
          </button>
        </form>
      </div>
    </div>
  );
};

export default CreatorStudio;
